"""Bahasa Indonesia — para nabi (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Nabi siapakah yang membangun bahtera atas perintah Allah?", ["Nuh", "Ibrahim", "Musa", "Yusuf"], "Allah memerintahkan Nuh membangun bahtera untuk menyelamatkan orang-orang beriman dari banjir besar."),
"prophets_002": ("Nabi siapakah yang dilemparkan ke dalam api yang Allah jadikan dingin dan selamat baginya?", ["Ibrahim", "Nuh", "Dawud", "Ayyub"], "Allah memerintahkan api menjadi dingin dan selamat bagi Ibrahim."),
"prophets_003": ("Nabi siapakah yang ditelan ikan besar?", ["Yunus", "Ilyas", "Idris", "Zakariyya"], "Yunus ditelan ikan setelah meninggalkan kaumnya dalam keadaan marah; Allah mengampuninya."),
"prophets_004": ("Nabi siapakah yang menafsirkan mimpi raja tentang tujuh sapi gemuk dan tujuh sapi kurus?", ["Yusuf", "Ya'qub", "Isma'il", "Ishaq"], "Yusuf menafsirkan mimpi raja: tujuh tahun kemakmuran diikuti tujuh tahun paceklik."),
"prophets_005": ("Menurut Al-Qur'an, nabi siapakah yang diajak bicara langsung oleh Allah?", ["Musa", "Harun", "Yusuf", "Sulaiman"], "Al-Qur'an menyatakan bahwa Allah berbicara langsung kepada Musa."),
"prophets_006": ("Nabi siapakah yang memahami bahasa burung?", ["Sulaiman", "Dawud", "Yunus", "Yusuf"], "Allah mengajarkan Sulaiman bahasa burung."),
"prophets_007": ("Nabi siapakah yang diberi kitab bernama Zabur?", ["Dawud", "Musa", "Isa", "Ibrahim"], "Al-Qur'an menyebutkan bahwa Zabur diberikan kepada Dawud."),
"prophets_008": ("Nabi siapakah yang lahir tanpa ayah, dengan firman Allah «Jadilah, maka jadilah»?", ["Isa", "Yahya", "Isma'il", "Ishaq"], "Al-Qur'an menggambarkan kelahiran Isa yang ajaib tanpa ayah, hanya dengan firman Allah."),
"prophets_009": ("Surah Al-Qur'an manakah yang dinamai dengan nama ibu seorang nabi?", ["Maryam", "Yusuf", "Nuh", "Hud"], "Surah ke-19, Maryam, dinamai dengan nama ibu Nabi Isa."),
"prophets_010": ("Nabi siapakah yang diuji dengan penyakit berat dan dipuji karena kesabarannya?", ["Ayyub", "Zakariyya", "Yahya", "Idris"], "Ayyub tetap sabar dalam ujian yang sangat berat, dan Allah membalasnya."),
"prophets_011": ("Kepada siapakah Allah memerintahkan para malaikat bersujud, sebagai tanda penghormatan?", ["Adam", "Nuh", "Ibrahim", "Musa"], "Allah memerintahkan para malaikat bersujud kepada Adam sebagai penghormatan, bukan penyembahan."),
"prophets_012": ("Nabi siapakah yang disebut «Khalilullah», kekasih Allah?", ["Ibrahim", "Musa", "Isa", "Muhammad ﷺ"], "Al-Qur'an menyebut Ibrahim sebagai kekasih (khalil) Allah."),
"prophets_013": ("Nabi siapakah yang dilempar ke dalam sumur oleh saudara-saudaranya?", ["Yusuf", "Bunyamin", "Ya'qub", "Isma'il"], "Saudara-saudara Yusuf melemparkannya ke sumur karena iri."),
"prophets_014": ("Kaum nabi siapakah yang dibinasakan banjir setelah menolaknya?", ["Nuh", "Hud", "Salih", "Syu'aib"], "Kaum Nuh ditenggelamkan banjir setelah terus-menerus menolak pesannya."),
"prophets_015": ("Nabi siapakah yang melihat laut terbelah untuk menyelamatkan kaumnya dari Fir'aun?", ["Musa", "Harun", "Yusuf", "Isma'il"], "Allah memerintahkan Musa memukul laut, dan laut terbelah sehingga orang-orang beriman dapat menyeberang."),
"prophets_016": ("Nabi siapakah yang bersama ayahnya Dawud memutuskan perkara ladang yang dimakan kambing?", ["Sulaiman", "Isma'il", "Yusuf", "Ishaq"], "Al-Qur'an menceritakan bahwa Sulaiman dan Dawud memutuskan perkara ini, dan Allah memberi Sulaiman pemahaman tentangnya."),
"prophets_017": ("Ibu siapakah yang diperintahkan meletakkan bayinya ke sungai?", ["Musa", "Isa", "Yusuf", "Isma'il"], "Allah mengilhami ibu Musa untuk meletakkannya dalam peti di sungai demi melindunginya."),
"prophets_018": ("Unta betina siapakah yang menjadi tanda bagi kaumnya, Tsamud?", ["Salih", "Hud", "Syu'aib", "Lut"], "Allah mengirim seekor unta betina sebagai tanda bagi kaum Tsamud melalui Nabi Salih."),
"prophets_019": ("Nabi siapakah yang diajari Allah nama-nama segala sesuatu?", ["Adam", "Nuh", "Ibrahim", "Musa"], "Allah mengajarkan Adam nama-nama segala sesuatu, dan para malaikat mengakui hikmah Allah."),
"prophets_020": ("Nabi siapakah yang berbicara kepada manusia saat masih bayi dalam buaian?", ["Isa", "Yahya", "Yusuf", "Ismail"], "Bayi Isa berbicara dari buaian: «Aku hamba Allah; Dia memberiku Kitab.»"),
"prophets_021": ("Bersama putra siapakah Ibrahim meninggikan dasar-dasar Ka'bah?", ["Ismail", "Ishaq", "Yaqub", "Yusuf"], "«Dan ketika Ibrahim meninggikan dasar-dasar Baitullah bersama Ismail…»: mereka membangun bersama."),
"prophets_022": ("Putra siapakah yang dikabarkan kepada Nabi Zakariyya di usia tuanya?", ["Yahya", "Isa", "Ismail", "Ishaq"], "«Wahai Zakariyya, Kami memberimu kabar gembira dengan seorang anak bernama Yahya.»"),
"prophets_023": ("Menjadi apakah tongkat Musa ketika Allah menyuruhnya melemparkannya?", ["Ular yang bergerak", "Burung", "Mata air", "Cahaya"], "«Lemparkanlah, wahai Musa!» Ia melemparkannya, dan tongkat itu menjadi ular yang bergerak cepat."),
"prophets_024": ("Dalam mimpinya, apakah yang dilihat Yusuf muda bersujud kepadanya?", ["Sebelas bintang, matahari dan bulan", "Tujuh sapi gemuk", "Hujan emas", "Kebun kurma"], "Yusuf melihat sebelas bintang, matahari dan bulan bersujud kepadanya: tanda takdirnya."),
"prophets_025": ("Kepada kaum manakah Nabi Hud diutus?", ["Kaum 'Ad", "Kaum Tsamud", "Penduduk Madyan", "Kaum Fir'aun"], "«Dan kepada kaum 'Ad, saudara mereka Hud…»: ia mengajak mereka menyembah Allah semata."),
"prophets_026": ("Kepada kaum manakah Nabi Syu'aib diutus?", ["Penduduk Madyan", "Kaum 'Ad", "Kaum Tsamud", "Kaum Nuh"], "«Dan kepada Madyan, saudara mereka Syu'aib…»: ia memerintahkan mereka menyempurnakan takaran dan timbangan."),
"prophets_027": ("Nabi siapakah yang disebut «Dzun-Nun» (pemilik ikan) dalam Al-Qur'an?", ["Yunus", "Musa", "Sulaiman", "Ayyub"], "«Dan Dzun-Nun, ketika ia pergi dalam keadaan marah…»: itulah Yunus, yang kemudian ditelan ikan."),
"prophets_028": ("Dalam surah manakah Musa melakukan perjalanan untuk belajar dari seorang hamba yang diberi Allah ilmu khusus?", ["Al-Kahf (Gua)", "Yusuf", "Maryam", "An-Naml"], "Dalam surah Al-Kahf, Musa menemani seorang hamba yang berilmu dan belajar bersabar atas apa yang belum ia pahami."),
"prophets_029": ("Nabi siapakah yang namanya paling sering disebut dalam Al-Qur'an?", ["Musa", "Ibrahim", "Nuh", "Isa"], "Musa adalah nabi yang paling sering disebut dalam Al-Qur'an; kisahnya dengan Fir'aun berulang kali diceritakan."),
"prophets_030": ("Berapa nabi yang disebut namanya dalam Al-Qur'an?", ["25", "10", "50", "99"], "Dua puluh lima nabi disebut namanya dalam Al-Qur'an, dari Adam hingga Muhammad ﷺ."),
"prophets_031": ("Dengan izin Allah, nabi siapakah yang menyembuhkan orang buta dan penderita kusta?", ["Isa", "Musa", "Dawud", "Yunus"], "Isa menyembuhkan orang buta dan penderita kusta dengan izin Allah: tanda bagi kaumnya."),
"prophets_032": ("Menurut Al-Qur'an, berapa lama Nuh tinggal di tengah kaumnya menyeru mereka kepada Allah?", ["950 tahun", "100 tahun", "300 tahun", "40 tahun"], "«Ia tinggal di tengah mereka seribu tahun kurang lima puluh»: 950 tahun seruan yang sabar."),
"prophets_033": ("Menurut Al-Qur'an, dari apakah Allah menciptakan Adam?", ["Dari tanah liat", "Dari cahaya", "Dari api", "Dari air"], "Allah berfirman kepada para malaikat: «Aku akan menciptakan manusia dari tanah liat.»"),
"prophets_034": ("Siapakah yang menggoda Adam dan istrinya untuk makan dari pohon terlarang?", ["Setan (Iblis)", "Malaikat", "Burung", "Raja"], "Setan membisikkan kepada mereka agar makan dari pohon yang dilarang Allah."),
"prophets_035": ("Alasan apakah yang diberikan Iblis untuk menolak bersujud kepada Adam?", ["«Aku lebih baik darinya: Engkau menciptakanku dari api dan dia dari tanah»", "Ia tidak tahu siapa Adam", "Ia takut pada malaikat", "Ia sedang tidur"], "Iblis menolak karena sombong: «Engkau menciptakanku dari api, sedangkan dia Engkau ciptakan dari tanah.»"),
"prophets_036": ("Setelah pembunuhan antara dua putra Adam, hewan apakah yang Allah kirim untuk menunjukkan cara mengubur jenazah?", ["Burung gagak", "Anjing", "Merpati", "Rubah"], "Allah mengirim seekor gagak yang menggali tanah untuk menunjukkan kepada si pembunuh cara menyembunyikan jenazah saudaranya."),
"prophets_037": ("Apa yang dikatakan Al-Qur'an tentang Nabi Idris?", ["Allah mengangkatnya ke tempat yang tinggi", "Ia membangun bahtera", "Ia ditelan ikan", "Ia berbicara dengan semut"], "«Dan Kami mengangkatnya ke tempat yang tinggi.»"),
"prophets_038": ("Apa yang dilakukan putra Nuh ketika ayahnya memanggilnya naik ke bahtera?", ["Ia menolak dan berkata akan berlindung di gunung", "Ia naik lebih dulu", "Ia membangun bahteranya sendiri", "Ia pergi mengumpulkan hewan"], "Ia berkata: «Aku akan berlindung ke gunung»; lalu gelombang menenggelamkannya."),
"prophets_039": ("Di gunung manakah bahtera Nuh berlabuh, menurut Al-Qur'an?", ["Gunung Judi", "Gunung Sinai", "Gunung Uhud", "Gunung Arafah"], "«Dan bahtera itu berlabuh di atas Gunung Judi.»"),
"prophets_040": ("Apa yang Allah perintahkan kepada Nuh untuk dimuat ke dalam bahtera?", ["Sepasang dari setiap jenis, dan orang-orang beriman", "Hanya keluarganya", "Hanya burung", "Emas dan perak"], "«Muatkanlah ke dalamnya sepasang dari setiap jenis, dan keluargamu… dan orang yang beriman.»"),
"prophets_041": ("Apa yang dilakukan para pemuka kaum Nuh ketika melihatnya membangun bahtera?", ["Mereka mengejeknya", "Mereka membantunya", "Mereka membawakan kayu", "Mereka berdoa bersamanya"], "Setiap kali para pemuka kaumnya lewat, mereka mengejeknya."),
"prophets_042": ("Bagaimana Al-Qur'an menggambarkan Nuh dalam surah Al-Isra?", ["Hamba yang banyak bersyukur", "Raja yang perkasa", "Pengembara besar", "Orang yang pendiam"], "«Sesungguhnya dia adalah hamba yang banyak bersyukur.»"),
"prophets_043": ("Bagaimana kaum 'Ad, tempat Hud diutus, dibinasakan?", ["Dengan angin kencang yang sangat dingin", "Dengan banjir", "Dengan hujan batu", "Dengan gempa"], "«Adapun kaum 'Ad, mereka dibinasakan dengan angin yang sangat dingin lagi kencang.»"),
"prophets_044": ("Apa yang menimpa Tsamud, kaum Salih?", ["Suara keras yang mengguntur", "Banjir", "Kelaparan", "Kawanan belalang"], "«Dan suara keras yang mengguntur menimpa orang-orang yang zalim.»"),
"prophets_045": ("Siapakah nama ayah Ibrahim yang disebut dalam Al-Qur'an?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim berkata kepada ayahnya, Azar: pantaskah engkau menjadikan berhala sebagai tuhan?»"),
"prophets_046": ("Setelah menghancurkan berhala-berhala, manakah yang Ibrahim biarkan utuh?", ["Yang terbesar", "Yang terkecil", "Yang dari emas", "Tidak ada, ia hancurkan semua"], "Ia menghancurkannya berkeping-keping, kecuali yang terbesar, agar kaumnya bertanya kepadanya."),
"prophets_047": ("Setelah melihat bintang, bulan, lalu matahari terbenam, apa yang dinyatakan Ibrahim?", ["«Aku tidak menyukai yang terbenam»", "«Matahari adalah tuhanku»", "«Bulan yang paling indah»", "«Aku akan tidur»"], "Setiap kali salah satunya terbenam, ia berkata: «Aku tidak menyukai yang terbenam», lalu berpaling kepada Sang Pencipta."),
"prophets_048": ("Berapa burung yang Allah suruh Ibrahim ambil, untuk menunjukkan bagaimana Dia menghidupkan yang mati?", ["Empat", "Dua", "Tujuh", "Dua belas"], "«Ambillah empat ekor burung… lalu panggillah, niscaya mereka datang kepadamu dengan segera.»"),
"prophets_049": ("Apa yang Ibrahim hidangkan kepada tamunya, para malaikat yang membawa kabar gembira?", ["Anak sapi panggang", "Kurma", "Susu", "Roti dan madu"], "«Tidak lama kemudian ia menyuguhkan daging anak sapi yang dipanggang.»"),
"prophets_050": ("Kabar gembira apakah yang para malaikat bawa kepada istri Ibrahim?", ["Kelahiran Ishaq", "Sebuah perjalanan", "Kekayaan besar", "Hujan yang lebat"], "«Kami sampaikan kabar gembira kepadanya tentang Ishaq, dan setelah Ishaq, Ya'qub.»"),
"prophets_051": ("Bagaimana reaksi putra Ibrahim ketika ayahnya menceritakan mimpi menyembelihnya?", ["Ia menerima: «Lakukanlah apa yang diperintahkan kepadamu»", "Ia melarikan diri", "Ia menangis dan menolak", "Ia bersembunyi"], "Ia berkata: «Wahai ayahku, lakukanlah apa yang diperintahkan kepadamu.» Dan Allah menebusnya dengan sembelihan yang besar."),
"prophets_052": ("Dalam doanya, di manakah Ibrahim mengatakan telah menempatkan sebagian keluarganya?", ["Di lembah tanpa tanaman, dekat Rumah Suci", "Di tepi Sungai Nil", "Di hutan", "Di sebuah pulau"], "«Aku telah menempatkan sebagian keturunanku di lembah yang tidak bertanaman di dekat Rumah-Mu yang suci.»"),
"prophets_053": ("Apa yang Ibrahim mohon bagi kota Makkah dalam doanya?", ["Agar menjadi kota yang aman dan penduduknya diberi buah-buahan", "Agar menjadi kerajaan", "Agar selalu turun hujan", "Agar memiliki sungai"], "«Ya Tuhanku, jadikanlah negeri ini aman dan berilah rezeki buah-buahan kepada penduduknya.»"),
"prophets_054": ("Saat meninggikan Ka'bah, Ibrahim dan Isma'il memohon kepada Allah agar mengutus di antara keturunan mereka…", ["Seorang rasul dari kalangan mereka yang membacakan ayat-ayat-Nya", "Seorang raja", "Sebuah pasukan", "Sebuah harta karun"], "«Ya Tuhan kami, utuslah di antara mereka seorang rasul dari kalangan mereka yang membacakan ayat-ayat-Mu.»"),
"prophets_055": ("Al-Qur'an menyebut seorang nabi, seorang diri, sebagai «umat». Siapakah?", ["Ibrahim", "Nuh", "Musa", "Sulaiman"], "«Sesungguhnya Ibrahim adalah seorang umat, yang patuh kepada Allah dan lurus.»"),
"prophets_056": ("Karena sifat apakah Al-Qur'an memuji Isma'il dalam surah Maryam?", ["Ia menepati janji", "Ia sangat kaya", "Ia seorang raja", "Ia pandai berenang"], "«Sesungguhnya dia benar janjinya, dan dia seorang rasul dan nabi.»"),
"prophets_057": ("Azab apakah yang menimpa kaum Lut?", ["Hujan batu dari tanah yang terbakar", "Banjir", "Kawanan serangga", "Kekeringan"], "«Kami jungkirbalikkan negeri itu dan Kami hujani mereka dengan batu dari tanah yang terbakar.»"),
"prophets_058": ("Istri dua nabi siapakah yang Al-Qur'an jadikan contoh kekafiran?", ["Nuh dan Lut", "Ibrahim dan Musa", "Dawud dan Sulaiman", "Ayyub dan Yunus"], "«Allah membuat perumpamaan bagi orang-orang kafir: istri Nuh dan istri Lut.»"),
"prophets_059": ("Siapakah ayah Ya'qub?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "Para malaikat mengabarkan kepada istri Ibrahim «Ishaq, dan setelah Ishaq, Ya'qub»."),
"prophets_060": ("Apa yang terjadi pada penglihatan Ya'qub karena menangisi Yusuf?", ["Matanya menjadi putih", "Ia melihat lebih baik di malam hari", "Tidak ada yang berubah", "Ia kehilangan satu mata"], "«Kedua matanya menjadi putih karena sedih, dan ia menahan amarahnya.»"),
"prophets_061": ("Apa yang memulihkan penglihatan Ya'qub?", ["Baju Yusuf yang diusapkan ke wajahnya", "Sebuah tanaman", "Air Zamzam", "Sebuah salep"], "Yusuf berkata: «Usapkanlah bajuku ini ke wajah ayahku; ia akan dapat melihat kembali.»"),
"prophets_062": ("Apa yang Yusuf pilih daripada menuruti ajakan yang tidak benar?", ["Penjara", "Pengasingan", "Kekayaan", "Diam"], "«Ya Tuhanku, penjara lebih aku sukai daripada apa yang mereka ajak aku kepadanya.»"),
"prophets_063": ("Di penjara, dua pemuda menceritakan mimpi mereka kepada Yusuf. Apa yang dilihat salah satunya?", ["Ia memeras anggur", "Ia terbang", "Ia menggembala domba", "Ia menggali sumur"], "Yang satu melihat dirinya memeras anggur, yang lain membawa roti di atas kepala yang dimakan burung."),
"prophets_064": ("Berapa tahun kemakmuran lalu kekeringan yang Yusuf ramalkan kepada raja?", ["Tujuh dan tujuh", "Tiga dan tiga", "Sepuluh dan sepuluh", "Satu dan satu"], "«Kamu akan bercocok tanam tujuh tahun… lalu akan datang tujuh tahun yang sulit.»"),
"prophets_065": ("Jabatan apakah yang Yusuf minta dari raja Mesir?", ["Perbendaharaan negeri", "Panglima pasukan", "Takhta", "Perbendaharaan emas"], "«Jadikanlah aku bendahara negeri: aku adalah orang yang pandai menjaga lagi berpengetahuan.»"),
"prophets_066": ("Apa yang Yusuf letakkan di karung adik bungsunya agar ia tetap bersamanya?", ["Piala minum raja", "Sekantong emas", "Sepucuk surat", "Bajunya"], "«Ia memasukkan piala ke dalam karung saudaranya.»"),
"prophets_067": ("Nasihat apakah yang Ya'qub berikan kepada putra-putranya sebelum masuk Mesir?", ["Masuk dari pintu-pintu yang berbeda", "Bepergian di malam hari", "Menyamar", "Membawa hadiah"], "«Janganlah kamu masuk dari satu pintu, tetapi masuklah dari pintu-pintu yang berbeda.»"),
"prophets_068": ("Mengapa saudara-saudara Yusuf datang ke Mesir ketika ia berkuasa di sana?", ["Untuk mendapatkan bahan makanan saat paceklik", "Untuk mencarinya", "Untuk berziarah", "Untuk menjual unta"], "Saudara-saudaranya datang untuk membeli gandum; mereka masuk menemuinya dan tidak mengenalinya."),
"prophets_069": ("Di rumah siapakah bayi Musa diambil setelah dihanyutkan ke sungai?", ["Fir'aun", "Seorang penggembala", "Seorang nelayan", "Seorang pedagang"], "Keluarga Fir'aun memungutnya, agar kelak ia menjadi musuh dan kesedihan bagi mereka."),
"prophets_070": ("Bagaimana bayi Musa akhirnya kembali kepada ibunya?", ["Ia menolak semua ibu susu, dan kakaknya mengusulkan ibunya", "Fir'aun mengembalikannya karena iba", "Ibunya mencurinya di malam hari", "Seorang malaikat membawanya"], "Allah membuatnya menolak para ibu susu; kakaknya mengusulkan sebuah keluarga: itulah ibunya, yang lalu menyusuinya."),
"prophets_071": ("Mengapa Musa harus segera meninggalkan Mesir, sebelum misinya?", ["Ia tanpa sengaja membunuh seorang pria dengan pukulan", "Ia mencuri dari istana", "Ia menolak membayar pajak", "Ia menghina Fir'aun"], "Ia memukul seorang Mesir yang berkelahi dengan orang dari kaumnya dan membunuhnya; ia langsung menyesal."),
"prophets_072": ("Siapakah yang memperingatkan Musa bahwa para pemuka berencana membunuhnya?", ["Seorang pria yang berlari dari ujung kota", "Ibunya", "Harun", "Seorang prajurit"], "«Seorang laki-laki datang bergegas dari ujung kota: mereka berunding untuk membunuhmu, maka keluarlah!»"),
"prophets_073": ("Setibanya di Madyan, apa yang Musa lakukan untuk dua wanita di tempat pengambilan air?", ["Ia memberi minum ternak mereka", "Ia menjual unta kepada mereka", "Ia membangun rumah untuk mereka", "Ia mengajari mereka membaca"], "Ia memberi minum ternak mereka, lalu berteduh sambil berdoa kepada Allah."),
"prophets_074": ("Berapa tahun orang tua di Madyan meminta Musa bekerja untuk menikahi putrinya?", ["Delapan, dan sepuluh jika ia mau", "Satu", "Empat puluh", "Tiga"], "«Engkau bekerja padaku delapan tahun; jika engkau cukupkan sepuluh, itu kebaikan darimu.»"),
"prophets_075": ("Apa yang Allah perintahkan Musa lepaskan di lembah suci Thuwa?", ["Sandalnya", "Jubahnya", "Tongkatnya", "Serbannya"], "«Lepaskanlah kedua sandalmu: engkau berada di lembah suci Thuwa.»"),
"prophets_076": ("Apakah tanda kedua yang diberikan kepada Musa, setelah tongkat?", ["Tangannya menjadi putih tanpa cacat", "Ia bisa terbang", "Suaranya menjadi guntur", "Ia bisa melihat di malam hari"], "«Kepitkanlah tanganmu ke ketiakmu: ia akan keluar putih tanpa cacat.»"),
"prophets_077": ("Apa yang Musa minta kepada Allah sebelum menemui Fir'aun?", ["Melapangkan dadanya dan melepaskan kekakuan lidahnya", "Sebuah pasukan", "Emas", "Kuda yang cepat"], "«Ya Tuhanku, lapangkanlah dadaku, mudahkanlah urusanku, dan lepaskanlah kekakuan lidahku.»"),
"prophets_078": ("Siapakah yang Musa minta kepada Allah sebagai pembantu dalam misinya?", ["Saudaranya Harun", "Putranya", "Mertuanya", "Seorang malaikat"], "«Jadikanlah untukku seorang pembantu dari keluargaku: Harun, saudaraku.»"),
"prophets_079": ("Apa yang dilakukan para penyihir Fir'aun ketika tongkat Musa menelan tipuan mereka?", ["Mereka bersujud dan beriman", "Mereka melarikan diri", "Mereka tertawa", "Mereka menyerang Musa"], "Para penyihir tersungkur bersujud: «Kami beriman kepada Tuhan semesta alam, Tuhan Musa dan Harun.»"),
"prophets_080": ("Manakah di antara bencana ini yang Al-Qur'an sebut dikirim kepada kaum Fir'aun?", ["Belalang", "Salju", "Serigala", "Api"], "«Kami kirimkan kepada mereka banjir, belalang, kutu, katak, dan darah.»"),
"prophets_081": ("Menurut Al-Qur'an, apa yang Allah lakukan terhadap jasad Fir'aun setelah ia tenggelam?", ["Menyelamatkannya sebagai tanda", "Melenyapkannya", "Membakarnya", "Mengembalikannya kepada kaumnya"], "«Pada hari ini Kami selamatkan jasadmu agar engkau menjadi pelajaran bagi orang-orang yang datang setelahmu.»"),
"prophets_082": ("Menurut Al-Qur'an, apa yang diminta istri Fir'aun yang beriman kepada Allah?", ["Sebuah rumah di sisi-Nya dalam surga", "Seorang putra", "Kematian Fir'aun", "Sebuah kerajaan"], "«Ya Tuhanku, bangunkanlah untukku sebuah rumah di sisi-Mu dalam surga, dan selamatkanlah aku dari Fir'aun.»"),
"prophets_083": ("Berapa malam perjanjian Allah dengan Musa di gunung berlangsung?", ["Empat puluh", "Tujuh", "Sepuluh", "Seratus"], "«Kami janjikan kepada Musa tiga puluh malam dan Kami sempurnakan dengan sepuluh: empat puluh malam.»"),
"prophets_084": ("Apa yang terjadi ketika Musa meminta melihat Allah?", ["Allah menampakkan diri kepada gunung, gunung hancur, dan Musa jatuh pingsan", "Ia melihat Allah", "Tidak terjadi apa-apa", "Gunung naik ke langit"], "«Lihatlah gunung itu: jika ia tetap di tempatnya, engkau akan melihat-Ku.» Gunung itu hancur luluh dan Musa jatuh pingsan."),
"prophets_085": ("Di atas apakah Allah menuliskan nasihat dan penjelasan bagi Musa?", ["Di atas Lauh (lempengan)", "Di atas daun kurma", "Di atas batu hitam", "Di atas kulit"], "«Kami tuliskan untuknya pada Lauh segala nasihat tentang segala sesuatu.»"),
"prophets_086": ("Siapakah yang membuat anak sapi yang disembah Bani Israil selagi Musa pergi?", ["Samiri", "Harun", "Fir'aun", "Qarun"], "«Samiri telah menyesatkan mereka»: dari perhiasan mereka ia membuat patung anak sapi yang bersuara."),
"prophets_087": ("Berapa mata air yang memancar dari batu yang dipukul Musa dengan tongkatnya?", ["Dua belas", "Tujuh", "Tiga", "Empat puluh"], "«Pukullah batu itu dengan tongkatmu»: memancarlah dua belas mata air, satu untuk setiap suku."),
"prophets_088": ("Makanan apakah yang Allah turunkan kepada Bani Israil di gurun?", ["Manna dan burung salwa", "Nasi dan ikan", "Kurma dan susu", "Roti dan zaitun"], "«Kami turunkan kepadamu manna dan salwa.»"),
"prophets_089": ("Apa warna sapi yang Musa perintahkan Bani Israil sembelih?", ["Kuning tua", "Hitam", "Putih", "Merah"], "«Sapi betina yang kuning tua warnanya, menyenangkan orang yang memandangnya.»"),
"prophets_090": ("Siapakah dari kaum Musa yang ditelan bumi beserta rumahnya karena kesombongan dan kekayaannya?", ["Qarun", "Haman", "Samiri", "Jalut"], "Qarun memiliki harta yang sangat banyak; «Kami benamkan dia beserta rumahnya ke dalam bumi.»"),
"prophets_091": ("Logam apakah yang Allah lunakkan untuk Dawud?", ["Besi", "Emas", "Tembaga", "Perak"], "«Dan Kami lunakkan besi untuknya.»"),
"prophets_092": ("Apa yang Allah ajarkan kepada Dawud untuk dibuat, demi melindungi manusia dalam peperangan?", ["Baju besi", "Pedang", "Perisai kayu", "Menara"], "«Kami ajarkan kepadanya membuat baju besi untuk melindungimu.»"),
"prophets_093": ("Raksasa siapakah yang Dawud bunuh dalam peperangan, menurut Al-Qur'an?", ["Jalut", "Fir'aun", "Haman", "Namrud"], "«Dan Dawud membunuh Jalut, lalu Allah memberinya kerajaan dan hikmah.»"),
"prophets_094": ("Bagaimana Raja Talut menguji pasukannya sebelum menghadapi Jalut?", ["Dengan sebuah sungai: jangan meminumnya, kecuali seceduk tangan", "Dengan perlombaan", "Dengan puasa tiga hari", "Dengan gunung yang harus didaki"], "«Allah akan mengujimu dengan sebuah sungai: siapa meminumnya bukan dari golonganku, kecuali seceduk tangan.»"),
"prophets_095": ("Apa yang Allah tundukkan untuk bertasbih bersama Dawud?", ["Gunung-gunung dan burung-burung", "Angin", "Jin", "Ikan"], "«Kami tundukkan gunung-gunung untuk bertasbih bersama Dawud, dan burung-burung.»"),
"prophets_096": ("Unsur apakah yang Allah tundukkan bagi Sulaiman untuk membawanya ke mana ia mau?", ["Angin", "Api", "Hujan", "Laut"], "«Dan bagi Sulaiman angin yang bertiup kencang atas perintahnya menuju negeri yang diberkahi.»"),
"prophets_097": ("Burung apakah yang membawa kabar tentang kerajaan Saba kepada Sulaiman?", ["Burung hud-hud", "Elang", "Merpati", "Gagak"], "Hud-hud kembali dan berkata: «Aku mengetahui sesuatu yang tidak engkau ketahui, dan aku membawa berita yang pasti dari Saba.»"),
"prophets_098": ("Makhluk kecil apakah yang memperingatkan kawanannya agar masuk sarang saat pasukan Sulaiman mendekat?", ["Semut", "Lebah", "Tikus", "Laba-laba"], "Seekor semut berkata: «Wahai semut, masuklah ke sarangmu agar Sulaiman dan bala tentaranya tidak menginjakmu tanpa sadar.»"),
"prophets_099": ("Seberapa cepat singgasana Ratu Saba dibawa kepada Sulaiman?", ["Sebelum matanya berkedip", "Dalam sehari", "Dalam tujuh hari", "Dalam sebulan"], "Orang yang memiliki ilmu dari Kitab berkata: «Aku akan membawanya kepadamu sebelum matamu berkedip.»"),
"prophets_100": ("Menurut Al-Qur'an, apa yang jin buat untuk Sulaiman?", ["Gedung-gedung tinggi, patung, dan kolam-kolam besar", "Karpet terbang", "Kapal", "Gunung"], "«Mereka membuat untuknya apa yang dikehendakinya: gedung-gedung tinggi, patung, piring sebesar kolam, dan periuk yang tetap.»"),
"prophets_101": ("Bagaimana jin mengetahui kematian Sulaiman?", ["Seekor rayap memakan tongkatnya dan ia pun jatuh", "Seorang malaikat memberi tahu", "Hud-hud memberi tahu", "Mereka melihatnya mati"], "Hanya «binatang bumi» yang memakan tongkatnya yang menyingkap kematiannya; jin pun sadar mereka tidak mengetahui yang gaib."),
"prophets_102": ("Doa khusus apakah yang Sulaiman panjatkan kepada Allah?", ["Kerajaan yang tidak dimiliki siapa pun setelahnya", "Umur panjang", "Kekayaan Qarun", "Kemampuan terbang"], "«Ya Tuhanku, ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak dimiliki siapa pun setelahku.»"),
"prophets_103": ("Apa yang Allah perintahkan Ayyub lakukan untuk memulihkan kesehatannya?", ["Menghentakkan kaki ke tanah: memancarlah mata air yang sejuk", "Berpuasa sebulan", "Mandi di laut", "Mendaki gunung"], "«Hentakkanlah kakimu: inilah air yang sejuk untuk mandi dan minum.»"),
"prophets_104": ("Doa apakah yang Yunus panjatkan dalam kegelapan perut ikan?", ["«Tidak ada tuhan selain Engkau! Mahasuci Engkau, sungguh aku termasuk orang yang zalim»", "«Ya Tuhanku, berilah aku kerajaan»", "«Ya Tuhanku, turunkanlah hujan»", "«Ya Tuhanku, izinkan aku melihat-Mu»"], "«Ia berseru dalam kegelapan: tidak ada tuhan selain Engkau! Mahasuci Engkau; sungguh aku termasuk orang yang zalim.»"),
"prophets_105": ("Tanaman apakah yang Allah tumbuhkan di atas Yunus setelah ikan memuntahkannya?", ["Tanaman labu (yaqtin)", "Pohon kurma", "Pohon zaitun", "Pohon anggur"], "«Dan Kami tumbuhkan untuknya sebatang pohon dari jenis labu.»"),
"prophets_106": ("Kepada berapa orang Yunus diutus, menurut Al-Qur'an?", ["Seratus ribu orang atau lebih", "Seribu", "Sepuluh ribu", "Dua belas"], "«Dan Kami utus dia kepada seratus ribu orang atau lebih.»"),
"prophets_107": ("Tanda apakah yang Allah berikan kepada Zakariyya untuk memastikan kedatangan putranya?", ["Tidak berbicara dengan manusia selama tiga malam padahal sehat", "Bintang jatuh", "Hujan di musim panas", "Sebuah mimpi"], "«Tandamu ialah engkau tidak dapat berbicara dengan manusia selama tiga malam, padahal engkau sehat.»"),
"prophets_108": ("Apa yang Allah katakan tentang nama Yahya?", ["Belum pernah ada yang diberi nama itu sebelumnya", "Itu nama kakeknya", "Ibunya yang memilih", "Itu nama seorang raja"], "«Kami memberimu kabar gembira dengan seorang anak bernama Yahya; Kami belum pernah memberikan nama itu kepada siapa pun sebelumnya.»"),
"prophets_109": ("Apa yang Allah anugerahkan kepada Yahya saat ia masih kanak-kanak?", ["Hikmah", "Kerajaan", "Kuda", "Harta karun"], "«Wahai Yahya, ambillah Kitab itu dengan sungguh-sungguh.» Dan Kami berikan hikmah kepadanya selagi ia masih kanak-kanak."),
"prophets_110": ("Apa yang ibu Maryam nazarkan untuk anak yang dikandungnya?", ["Mengabdikannya untuk berkhidmat kepada Allah", "Mengirimnya ke Mesir", "Menjadikannya raja", "Menitipkannya kepada penggembala"], "«Ya Tuhanku, aku menazarkan kepada-Mu apa yang ada dalam kandunganku untuk berkhidmat kepada-Mu.»"),
"prophets_111": ("Nabi siapakah yang mengasuh Maryam setelah kelahirannya?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "«Dan Allah menjadikan Zakariyya sebagai pengasuhnya», yang mendapati rezeki dari Allah di sisinya."),
"prophets_112": ("Menurut Al-Qur'an, Allah memilih Maryam di atas siapa?", ["Perempuan-perempuan seluruh alam", "Para ratu", "Para malaikat", "Para nabi"], "«Wahai Maryam, Allah telah memilihmu, menyucikanmu, dan melebihkanmu di atas perempuan-perempuan seluruh alam.»"),
"prophets_113": ("Apa yang jatuh untuk Maryam ketika ia menggoyangkan batang pohon kurma?", ["Kurma yang masak dan segar", "Zaitun", "Buah ara", "Hujan"], "«Goyanglah pangkal pohon kurma itu ke arahmu, niscaya ia menjatuhkan kurma yang masak kepadamu.»"),
"prophets_114": ("Kata apakah yang Al-Qur'an gunakan untuk Maryam dalam surah Al-Ma'idah?", ["Siddiqah (yang benar)", "Ratu", "Nabi perempuan", "Pejuang"], "«Al-Masih putra Maryam hanyalah seorang rasul… dan ibunya seorang yang benar (siddiqah).»"),
"prophets_115": ("Gelar apakah yang Al-Qur'an berikan kepada Isa putra Maryam?", ["Al-Masih", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "«Namanya Al-Masih Isa putra Maryam, terkemuka di dunia dan di akhirat.»"),
"prophets_116": ("Apa yang Isa bentuk dari tanah, dengan izin Allah?", ["Bentuk burung, yang kemudian hidup", "Sebuah rumah", "Patung raja", "Sebuah perahu"], "«Aku membuat untukmu dari tanah berbentuk burung, lalu aku meniupnya, maka ia menjadi burung dengan izin Allah.»"),
"prophets_117": ("Apa sebutan bagi para sahabat dekat Isa yang menyatakan diri sebagai «penolong Allah»?", ["Hawariyyun (pengikut setia)", "Anshar", "Muhajirin", "Sahabat Nabi"], "«Para hawariyyun berkata: kamilah penolong-penolong Allah.»"),
"prophets_118": ("Apa yang para hawariyyun minta kepada Isa, yang menjadi nama surah Al-Ma'idah?", ["Hidangan yang diturunkan dari langit", "Sebuah kitab", "Sebuah kerajaan", "Emas"], "«Sanggupkah Tuhanmu menurunkan hidangan dari langit kepada kami?»"),
"prophets_119": ("Apa yang Al-Qur'an katakan tentang akhir misi Isa di bumi?", ["Ia tidak dibunuh dan tidak disalib: Allah mengangkatnya kepada-Nya", "Ia wafat karena tua", "Ia tenggelam", "Ia pergi ke Mesir"], "«Mereka tidak membunuhnya dan tidak menyalibnya… tetapi Allah mengangkatnya kepada-Nya.»"),
"prophets_120": ("Dengan nama apakah Isa mengabarkan seorang rasul yang akan datang setelahnya?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…memberi kabar gembira tentang seorang rasul yang akan datang setelahku, namanya Ahmad.»"),
"prophets_121": ("Berhala apakah yang Nabi Ilyas kecam kaumnya karena menyembahnya?", ["Ba'l", "Hubal", "Al-Lata", "Wadd"], "«Pantaskah kamu menyembah Ba'l dan meninggalkan sebaik-baik pencipta?»"),
"prophets_122": ("Tiga nabi manakah yang Al-Qur'an sebut bersama sebagai «orang-orang yang sabar»?", ["Isma'il, Idris dan Dzulkifli", "Nuh, Hud dan Salih", "Musa, Harun dan Yusya'", "Dawud, Sulaiman dan Ayyub"], "«Dan Isma'il, Idris dan Dzulkifli: semuanya termasuk orang-orang yang sabar.»"),
"prophets_123": ("Nabi siapakah yang disebut dalam surah Sad bersama Isma'il dan Dzulkifli?", ["Ilyasa'", "Yunus", "Lut", "Syu'aib"], "«Dan ingatlah Isma'il, Ilyasa' dan Dzulkifli: semuanya termasuk orang-orang terbaik.»"),
"prophets_124": ("Gelar apakah yang Al-Qur'an berikan kepada Nabi Muhammad ﷺ dalam ayat 33:40?", ["Penutup para nabi", "Raja bangsa Arab", "Bapak orang-orang beriman", "Kekasih Allah"], "«Muhammad… adalah Rasulullah dan penutup para nabi.»"),
"prophets_125": ("Menurut Al-Qur'an, sebagai apakah Nabi Muhammad ﷺ diutus?", ["Sebagai rahmat bagi seluruh alam", "Sebagai raja", "Sebagai hakim", "Sebagai prajurit"], "«Kami tidak mengutusmu melainkan sebagai rahmat bagi seluruh alam.»"),
"prophets_126": ("Menurut ayat 33:56, apa yang Allah dan para malaikat-Nya lakukan untuk Nabi ﷺ?", ["Bershalawat kepadanya", "Melindunginya dari angin", "Mengirimkan hujan", "Mengawasinya dalam diam"], "«Allah dan para malaikat-Nya bershalawat untuk Nabi. Wahai orang-orang beriman, bershalawatlah dan ucapkanlah salam kepadanya!»"),
"prophets_127": ("Bagaimana Al-Qur'an menggambarkan akhlak Nabi ﷺ dalam surah Al-Qalam?", ["«Engkau benar-benar berbudi pekerti yang agung»", "«Engkau raja yang agung»", "«Engkau yang terkaya»", "«Engkau yang terkuat»"], "«Dan sesungguhnya engkau benar-benar berbudi pekerti yang agung.»"),
"prophets_128": ("Apa yang diingatkan ayat 3:144 tentang Muhammad ﷺ?", ["Ia hanyalah seorang rasul, dan sebelumnya telah berlalu para rasul", "Ia tidak akan pernah wafat", "Ia seorang malaikat", "Ia mengetahui masa depan"], "«Muhammad hanyalah seorang rasul; sebelumnya telah berlalu beberapa rasul.»"),
"prophets_129": ("Lima nabi manakah yang disebut bersama dalam ayat 33:7 untuk perjanjian yang teguh?", ["Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ", "Adam, Nuh, Hud, Salih dan Lut", "Dawud, Sulaiman, Ayyub, Yunus dan Idris", "Isma'il, Ishaq, Ya'qub, Yusuf dan Musa"], "«Kami mengambil perjanjian dari para nabi: darimu, dari Nuh, Ibrahim, Musa dan Isa putra Maryam.»"),
"prophets_130": ("Menurut hadis dalam Sahih al-Bukhari, pekerjaan apakah yang dilakukan setiap nabi?", ["Menggembala", "Tukang kayu", "Pandai besi", "Pedagang"], "«Allah tidak mengutus seorang nabi pun kecuali ia pernah menggembala kambing», dan Nabi ﷺ menggembalanya untuk penduduk Makkah."),
"prophets_131": ("Menurut hadis dalam Sahih Muslim, nabi siapakah yang bekerja sebagai tukang kayu?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "Nabi ﷺ bersabda: «Zakariyya adalah seorang tukang kayu.»"),
"prophets_132": ("Tentang nabi siapakah Nabi ﷺ bersabda bahwa beliau «yang paling dekat» dengannya, di dunia dan akhirat?", ["Isa putra Maryam", "Musa", "Ibrahim", "Nuh"], "«Aku adalah manusia yang paling dekat dengan Isa putra Maryam di dunia dan akhirat; para nabi itu bersaudara.»"),
"prophets_133": ("Berapa surah Al-Qur'an yang dinamai dengan nama seorang nabi?", ["Enam", "Dua", "Dua belas", "Dua puluh lima"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) dan Nuh (71)."),
"prophets_134": ("Dengan tiga kata apakah Al-Qur'an menggambarkan Ibrahim dalam ayat 11:75?", ["Penyantun, lembut hati, selalu kembali kepada Allah", "Kaya, berkuasa, terpelajar", "Kuat, cepat, berani", "Raja, hakim, pejuang"], "«Sesungguhnya Ibrahim itu penyantun, lembut hati, dan selalu kembali kepada Allah.»"),
"prophets_135": ("Selain penyembahan berhala, apa yang Syu'aib kecam dari kaumnya?", ["Mengurangi takaran dan timbangan", "Tidak salat", "Bepergian malam hari", "Makan ikan"], "«Sempurnakanlah takaran dan timbangan, dan janganlah kamu merugikan hak orang lain.»"),
"prophets_136": ("Apa yang menimpa kaum Syu'aib setelah menolak pesannya?", ["Gempa bumi", "Banjir", "Hujan api", "Kawanan burung"], "«Maka gempa menimpa mereka, dan mereka mati bergelimpangan di rumah mereka.»"),
"prophets_137": ("Kabar apakah yang para malaikat berikan kepada Ibrahim setelah menenangkan ketakutannya?", ["Bahwa mereka diutus kepada kaum Lut", "Bahwa banjir akan datang", "Bahwa Ka'bah akan dihancurkan", "Bahwa Fir'aun akan tenggelam"], "«Jangan takut: kami diutus kepada kaum Lut.»"),
"prophets_138": ("Apa yang Ibrahim mohon untuk dirinya dan keturunannya dalam ayat 14:40?", ["Menjadi orang yang mendirikan salat", "Menjadi raja", "Menjadi kaya", "Berumur panjang"], "«Ya Tuhanku, jadikanlah aku dan anak cucuku orang yang tetap mendirikan salat.»"),
"prophets_139": ("Di akhir kisah Yusuf, siapakah yang ia naikkan ke singgasana sebelum semua bersujud kepadanya?", ["Kedua orang tuanya", "Raja", "Saudara-saudaranya", "Putranya"], "«Ia menaikkan kedua orang tuanya ke singgasana, dan mereka tersungkur sujud kepadanya»: mimpi masa kecil pun terwujud."),
"prophets_140": ("Mengapa saudara-saudara Yusuf ingin menyingkirkannya?", ["Karena iri: ayah mereka lebih menyayanginya", "Ia mencuri", "Ia menolak bekerja", "Ia sakit"], "«Yusuf dan saudaranya lebih dicintai ayah kita daripada kita… Bunuhlah Yusuf atau buanglah dia ke suatu tempat.»"),
"prophets_141": ("Apa yang saudara-saudara Yusuf bawa kepada ayah mereka agar ia percaya serigala telah memakannya?", ["Bajunya yang dilumuri darah palsu", "Sandalnya", "Tongkatnya", "Gigi serigala"], "«Mereka datang membawa bajunya dengan darah palsu»; Ya'qub menjawab: «Kesabaran yang baik itulah yang lebih indah.»"),
"prophets_142": ("Apa yang Allah janjikan kepada ibu Musa ketika mengilhaminya menghanyutkan Musa ke sungai?", ["Mengembalikannya kepadanya dan menjadikannya rasul", "Memberinya putra lain", "Menjadikannya ratu", "Menurunkan hujan"], "«Jangan takut dan jangan bersedih: Kami akan mengembalikannya kepadamu dan menjadikannya salah seorang rasul.»"),
"prophets_143": ("Dengan apakah Musa memukul laut sehingga terbelah?", ["Tongkatnya", "Tangannya", "Batu", "Pedangnya"], "«Pukullah laut itu dengan tongkatmu»: laut pun terbelah, dan setiap belahan seperti gunung yang besar."),
"prophets_144": ("Apa hal pertama yang Allah firmankan kepada Musa ketika berbicara kepadanya?", ["«Akulah Allah, tidak ada tuhan selain Aku: sembahlah Aku dan dirikanlah salat»", "«Pergilah memancing»", "«Buatlah bahtera»", "«Kembalilah kepada Fir'aun»"], "«Sesungguhnya Aku adalah Allah; tidak ada tuhan selain Aku, maka sembahlah Aku dan dirikanlah salat untuk mengingat-Ku.»"),
"prophets_145": ("Bagaimana Allah menyuruh Musa dan Harun berbicara kepada Fir'aun?", ["Dengan kata-kata yang lembut", "Dengan marah", "Dengan berteriak", "Dengan diam"], "«Pergilah kepada Fir'aun… dan bicaralah kepadanya dengan kata-kata yang lembut; mudah-mudahan ia ingat atau takut.»"),
"prophets_146": ("Apa yang Musa katakan kepada pembantu mudanya di awal perjalanan menuju pertemuan dua laut?", ["Bahwa ia tidak akan berhenti hingga sampai di pertemuan dua laut", "Bahwa ia ingin pulang", "Bahwa ia takut", "Bahwa ia mencari emas"], "«Aku tidak akan berhenti sebelum sampai di pertemuan dua laut, walaupun aku harus berjalan bertahun-tahun.»"),
"prophets_147": ("Manakah yang dilakukan hamba berilmu itu di hadapan Musa, yang saat itu tidak dipahaminya?", ["Ia melubangi sebuah perahu", "Ia membangun jembatan", "Ia menyalakan api", "Ia menanam pohon"], "Ia melubangi perahu, lalu membunuh seorang anak, lalu menegakkan dinding; setelahnya ia menjelaskan setiap perbuatan kepada Musa."),
"prophets_148": ("Apa kata-kata pertama Isa saat masih dalam buaian?", ["«Aku hamba Allah; Dia memberiku Kitab dan menjadikanku nabi»", "«Aku putra Tuhan»", "«Aku seorang raja»", "«Aku lapar»"], "«Ia berkata: sesungguhnya aku hamba Allah. Dia memberiku Kitab dan menjadikanku seorang nabi.»"),
"prophets_149": ("Apa yang Adam dan istrinya katakan kepada Allah setelah makan dari pohon itu?", ["«Ya Tuhan kami, kami telah menzalimi diri sendiri; jika Engkau tidak mengampuni kami, kami akan merugi»", "«Bukan salah kami»", "«Itu salah pohonnya»", "Mereka tidak berkata apa-apa"], "«Ya Tuhan kami, kami telah menzalimi diri kami sendiri, dan jika Engkau tidak mengampuni dan merahmati kami, niscaya kami termasuk orang-orang yang rugi.»"),
"prophets_150": ("Misi apakah yang Allah berikan kepada Nuh terhadap kaumnya, dalam ayat pertama surah Nuh?", ["Memperingatkan mereka sebelum datang azab yang pedih", "Membangun kota", "Mengajari mereka memancing", "Menjadikan mereka raja"], "«Kami mengutus Nuh kepada kaumnya: berilah peringatan kepada kaummu sebelum datang azab yang pedih.»"),
}
